            if "outputs" in response.json():
                outputs = response.json()["outputs"]
                print("Demo outputs received:", len(outputs))
                import sys; print(json.dumps(outputs, indent=2))
            elif "demo" in response.json():
                # Single demo pair
                d = response.json()
                if "output" in d and isinstance(d["output"], list):
                    output_grid = d["output"]
                    input_grid = d["input"]
                    print("Demo input:", json.dumps(input_grid))
                    print("Demo output:", json.dumps(output_grid))
        else:
            print("Response:", response.json())
    else:
        print("Error:", response.text)
except Exception as e:
    print(f"Error parsing: {e}")
    print(response.text)

